/* ==UserStyle==
@name Phanpy Catppuccin
@namespace github.com/catppuccin/userstyles/styles/phanpy
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/phanpy
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/phanpy/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Aphanpy
@description Soothing pastel theme for Phanpy
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("phanpy.social") {
  :root:not(:has(.is-light)) {
    #catppuccin(@darkFlavor);
  }
  :root.is-light {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --text-color: @text;
    --text-insignificant-color: @subtext0;
    --link-color: @accent;
    --link-text-color: @accent;
    --link-faded-color: @accent;
    --link-light-color: @accent;
    --button-bg-blur-color: @accent;
    --button-bg-color: @accent;
    --button-text-color: @base;
    --bg-faded-color: @base;
    --bg-faded-blur-color: @mantle;
    --bg-blur-color: @mantle;
    --close-button-bg-color: @mantle;
    --close-button-color: @subtext0;
    --bg-color: @base;
    --link-bg-hover-color: @mantle;
    --divider-color: @surface0;
    --outline-color: @surface0;
    --outline-hover-color: @surface2;
    --reblog-faded-color: fade(@mauve, 20%);
    --reblog-color: @mauve;
    --reply-to-faded-color: fade(@yellow, 20%);
    --reply-to-text-color: @yellow;
    --reply-to-color: @yellow;
    --favourite-color: @red;
    --green-color: @green;
    --red-color: @red;
    --comment-line-color: @surface1;
    --media-bg-color: @base;
    --media-fg-color: @text;
    --media-outline-color: @text;

    .szh-menu__item--disabled {
      color: @subtext0;
    }

    .button.plain2 {
      background-color: @mantle;
    }

    .replies-parent-link {
      background-color: @surface0 !important;
    }

    .account-container {
      --original-color: @blue;

      .profile-field,
      .stats,
      .posting-stats-button {
        background-color: @mantle;
        -webkit-filter: none;
        filter: none;
      }
    }
  }
}

